gvp(){return"\u0645\u062a\u0627\u062d\u0629 \u0639\u0644\u0649 \u0627\u0644\u0643\u0645\u0628\u064a\u0648\u062a\u0631 / \u0627\u0644\u0634\u0627\u0634\u0629 \u0627\u0644\u0643\u0628\u064a\u0631\u0629"},
guw(){return"\u0627\u0644\u062a\u0628\u062f\u064a\u0644 \u0628\u064a\u0646 \u0627\u0644\u0623\u0642\u0633\u0627\u0645"},
guv(){return"\u0628\u062d\u062b"},
gut(){return"\u0625\u063a\u0644\u0627\u0642 \u0627\u0644\u0635\u0641\u062d\u0629"},
